def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    wall = Counter(x for row in grid for x in row if x != bg).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def decorate(r0, r1, c0, c1):
        if r1 <= r0 or c1 <= c0:
            return
        best, best_score = [], -1
        for r, c, dr, dc in ((r0,c0,1,1), (r0,c1,1,-1),
                             (r1,c0,-1,1), (r1,c1,-1,-1)):
            vals = []
            started = False
            while r0 <= r <= r1 and c0 <= c <= c1:
                v = grid[r][c]
                if v == bg:
                    if started:
                        break
                else:
                    started = True
                vals.append(v)
                r += dr
                c += dc
            while vals and vals[-1] == bg:
                vals.pop()
            score = sum(v != bg for v in vals)
            if score > best_score:
                best_score, best = score, vals
        if not best:
            return
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if grid[r][c] == wall:
                    continue
                d = min(r-r0, r1-r, c-c0, c1-c)
                out[r][c] = best[d] if d < len(best) else bg

    # Main regions are delimited by separator lines spanning the grid/zone.
    sep_cols = [c for c in range(w) if all(grid[r][c] == wall for r in range(h))]
    cuts = [-1] + sep_cols + [w]
    for a, b in zip(cuts, cuts[1:]):
        c0, c1 = a+1, b-1
        if c0 > c1:
            continue
        rows = [r for r in range(h)
                if all(grid[r][c] == wall for c in range(c0, c1+1))]
        rcuts = [-1] + rows + [h]
        for x, y in zip(rcuts, rcuts[1:]):
            decorate(x+1, y-1, c0, c1)

    # Also decorate any smaller closed rectangular rooms embedded in a region.
    rectangles = []
    for r0 in range(h):
        for r1 in range(r0+2, h):
            for c0 in range(w):
                for c1 in range(c0+2, w):
                    if (all(grid[r0][c] == wall for c in range(c0,c1+1))
                        and all(grid[r1][c] == wall for c in range(c0,c1+1))
                        and all(grid[r][c0] == wall for r in range(r0,r1+1))
                        and all(grid[r][c1] == wall for r in range(r0,r1+1))):
                        rectangles.append((r0,r1,c0,c1))
    # Smaller rooms last, so their own pattern takes precedence.
    for r0, r1, c0, c1 in sorted(rectangles,
                                 key=lambda z: (z[1]-z[0])*(z[3]-z[2]),
                                 reverse=True):
        decorate(r0, r1, c0, c1)
    return out
